import json,hashlib,html
from pathlib import Path
from collections import Counter
ROOT=Path('evaluation/inputs/preregistered-mixed-regression-2026-11-03')
OUT=Path('evaluation/private/preregistered-mixed-regression-2026-11-03')
def digest(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def build():
 protected=json.loads((ROOT/'original-hashes.json').read_text())
 assert all(digest(p)==h for p,h in protected.items()),'Original evidence changed'
 before=json.loads(Path('evaluation/preregistered-mixed-2026-11-03.json').read_text())
 after=json.loads((OUT/'results.json').read_text())
 old=json.loads(Path('evaluation/inputs/preregistered-mixed-2026-11-03/manifest.json').read_text())
 new=json.loads((ROOT/'manifest.json').read_text())
 assert old['cases']==new['cases']
 assert len(before['rows'])==len(after['rows'])==21
 assert [r['id'] for r in before['rows']]==[r['id'] for r in after['rows']]
 for c in new['cases']:
  for f in c['files'].values():assert digest(f['path'])==f['sha256']
 for p,h in new['code_sha256'].items():assert digest(ROOT/'runtime'/p)==h
 rows=[{'id':a['id'],'expected':a['expected_action'],'before':b,'after':a} for b,a in zip(before['rows'],after['rows'])]
 report={'scope':'Regression, not fresh holdout. Same 7 photos and 21 synthetic controls. No ERP writes. Model failures are not correct decisions.', 'original_files_preserved':True,'unchanged_inputs_and_targets':True,'before_counts':dict(Counter(r['action'] for r in before['rows'])),'after_counts':dict(Counter(r['action'] for r in after['rows'])),'manifest_sha256':digest(ROOT/'manifest.json'),'previous_manifest_sha256':digest(Path('evaluation/inputs/preregistered-mixed-2026-11-03/manifest.json')),'offline_tests':{'passed':165,'physical_image_inference':False},'connection_probe':{'github_https':200,'meta_status_https':'TLS connection timeout, IPv4 and IPv6','interpretation':'Reachability from this machine failed. Not evidence of a global outage or an authentication failure.'},'rows':rows}
 site=Path('site/preregistered-mixed-regression');site.mkdir(exist_ok=True)
 payload=json.dumps(report,ensure_ascii=False,indent=2)
 (site/'results.json').write_text(payload)
 Path('evaluation/preregistered-mixed-regression-2026-11-03.json').write_text(payload)
 labels={
 'tr':['Aynı 21 kontrol: önce / sonra','Eski kanıtlar korundu. Fotoğraf, belge, ses ve hedefler değişmedi.','Ambalaj kontrolü eklendi; açık, hasarlı, belirsiz veya eksik koşul otomatik kabulü durdurur. API istemcisi yeniden kullanılıyor; bağlantı beklemesi sınırlandı, hata türleri kaydediliyor.','Bağlantı hatası doğru karar değildir. 5183 düzeltmesinin fotoğraf üzerindeki başarısı ancak modelden yeni sonuç alınırsa doğrulanabilir.','165 çevrimdışı test geçti. Bu, fotoğrafların model tarafından yeniden doğrulandığı anlamına gelmez.','Vaka','Hedef','Önce','Sonra','Süre (sn)','Hata / kural','İlk rapor','Tüm ham sonuçlar (JSON)','7 fotoğraf, 21 ilişkili kontrol; gerçek bağımsız teslimatlar değil. Gerçek ERP kaydı yok. Bu koşu artık regresyon testidir.','Ham kanıt — değiştirilmeden','Önceki dağılım','Yeni dağılım','kabul','ret','insan incelemesi','teknik hata','temel senaryo','yanlış miktar','belirsiz sayım'],
 'en':['Same 21 controls: before / after','Original evidence preserved. Photos, documents, audio and targets are unchanged.','Added packaging inspection: open, damaged, uncertain or missing condition stops automatic acceptance. The API client is reused, connection waits are bounded and error types are recorded.','A connection failure is not a correct decision. The image-level fix for 5183 can only be confirmed with a fresh model result.','165 offline tests passed. This does not mean the photographs have been revalidated by the models.','Case','Target','Before','After','Time (s)','Error / rule','Original report','All raw results (JSON)','7 photographs, 21 correlated controls; not independent real deliveries. No ERP writes. This run is now a regression test.','Raw evidence — unchanged','Previous distribution','New distribution','accept','reject','human review','technical error','baseline','wrong quantity','uncertain count'],
 'de':['Dieselben 21 Kontrollen: vorher / nachher','Alte Nachweise bleiben erhalten. Fotos, Dokumente, Audio und Ziele sind unverändert.','Verpackungsprüfung ergänzt: offene, beschädigte, unklare oder fehlende Zustandsangaben verhindern die automatische Annahme. Der API-Client wird wiederverwendet; Verbindungswartezeiten sind begrenzt, Fehlertypen werden erfasst.','Ein Verbindungsfehler ist keine richtige Entscheidung. Die Korrektur für Foto 5183 kann erst mit einem neuen Modellergebnis bestätigt werden.','165 Offline-Tests bestanden. Das bedeutet keine erneute Modellvalidierung der Fotos.','Fall','Ziel','Vorher','Nachher','Zeit (s)','Fehler / Regel','Ursprünglicher Bericht','Alle Rohdaten (JSON)','7 Fotos, 21 zusammenhängende Kontrollen; keine unabhängigen realen Lieferungen. Keine ERP-Buchungen. Dieser Lauf ist ein Regressionstest.','Unveränderte Rohnachweise','Frühere Verteilung','Neue Verteilung','Annahme','Ablehnung','menschliche Prüfung','technischer Fehler','Basisfall','falsche Menge','unklare Zählung'],
 'zh':['相同的21项检查：修复前后','保留原始证据。照片、单据、音频和预期结果均未改变。','新增包装检查：包装打开、损坏、状态不确定或缺失时，禁止自动验收。复用API客户端，限制连接等待时间，并记录错误类型。','连接失败不代表正确判断。只有获得新的模型结果，才能确认照片5183的修复效果。','165项离线测试通过。这不代表模型已重新验证照片。','案例','预期','修复前','修复后','时间（秒）','错误／规则','原始报告','全部原始结果（JSON）','7张照片，21项相关检查，并非独立的真实交货。未写入ERP。本轮属于回归测试。','原始证据（未修改）','原始分布','最新分布','验收','拒收','人工审核','技术错误','基准案例','数量错误','计数不确定']}
 data=json.dumps(report,ensure_ascii=False).replace('<','\\u003c')
 page='''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Count Before You Post — Regression</title><style>body{background:#f5f4ee;color:#17313e;font:16px/1.6 system-ui;margin:0}main{max-width:1200px;margin:auto;padding:32px 20px}h1{font-size:38px;line-height:1.2}.notice{background:#fff1da;padding:20px;border-left:4px solid #ba7023}table{width:100%;border-collapse:collapse;background:white}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;padding:16px;font-size:12px}select{padding:10px}a{color:#175bdb}</style><main><select id="lang" aria-label="Language"><option value="tr">Türkçe</option><option value="en">English</option><option value="de">Deutsch</option><option value="zh">中文</option></select><h1 data-t="0"></h1><p data-t="1"></p><p data-t="2"></p><section class="notice"><strong data-t="3"></strong><p data-t="4"></p></section><p id="counts"></p><p data-t="13"></p><p><a href="../preregistered-mixed/" data-t="11" id="original"></a> · <a href="results.json" data-t="12"></a></p><div class="scroll"><table><thead><tr><th data-t="5"></th><th data-t="6"></th><th data-t="7"></th><th data-t="8"></th><th data-t="9"></th><th data-t="10"></th></tr></thead><tbody id="rows"></tbody></table></div><details><summary data-t="14"></summary><pre id="raw"></pre></details></main><script>const report=REPORT, translations=LABELS; const selector=document.querySelector('#lang'); function render(lang){const t=translations[lang]||translations.tr;document.documentElement.lang=lang;selector.value=lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t[Number(el.dataset.t)]);const names={post:t[17],block:t[18],human:t[19],error:t[20]};const counts=x=>Object.entries(x).map(([k,v])=>v+' '+names[k]).join(' · ');document.querySelector('#counts').textContent=t[15]+': '+counts(report.before_counts)+' | '+t[16]+': '+counts(report.after_counts);document.querySelector('#original').href='../preregistered-mixed/?ui='+lang;const tbody=document.querySelector('#rows');tbody.replaceChildren();for(const r of report.rows){const tr=document.createElement('tr');for(const text of [String(r.after.source_image_id)+' · '+t[{baseline:21,quantity_mismatch:22,receiver_uncertain:23}[r.after.scenario]],names[r.expected],names[r.before.action],names[r.after.action],r.before.seconds+' → '+r.after.seconds,(r.before.rule||r.before.error_type)+' → '+(r.after.error_chain?.join(' / ')||r.after.rule||r.after.error_type)]){const td=document.createElement('td');td.textContent=text;tr.append(td)}tbody.append(tr)}document.querySelector('#raw').textContent=JSON.stringify(report,null,2);}selector.addEventListener('change',()=>{const u=new URL(location);u.searchParams.set('ui',selector.value);history.replaceState(null,'',u);localStorage.setItem('cbyp-ui-language',selector.value);render(selector.value)});let lang=new URL(location).searchParams.get('ui')||localStorage.getItem('cbyp-ui-language')||'tr';render(translations[lang]?lang:'tr');</script></html>'''
 page=page.replace('REPORT',data).replace('LABELS',json.dumps(labels,ensure_ascii=False))
 (site/'index.html').write_text(page)
 print(json.dumps({k:v for k,v in report.items() if k!='rows'},ensure_ascii=False,indent=2))
if __name__=='__main__':build()
